 void RegisterScene(string wld,SageSceneDocument scene,string? scope=null)
 {
  foreach(var sm in scene.Meshes.Where(x=>x.Primitives.Count>0)){
   var key=scope is null?$"{wld}#{sm.Name}":$"{wld}#{scope}#{sm.Name}";
   var rp=sm.Primitives.Select(p=>{var m=scene.Materials[p.MaterialIndex];var processed=m.Frames.Select(x=>ProcessedTexture(x.FileName,m.Shader)).Where(x=>x is not null).Cast<string>().ToArray();var tex=processed.FirstOrDefault();var blend=m.Shader is SageShaderType.Transparent25 or SageShaderType.Transparent50 or SageShaderType.Transparent75 or SageShaderType.TransparentAdditive or SageShaderType.TransparentAdditiveUnlit or SageShaderType.TransparentSkydome or SageShaderType.TransparentAdditiveUnlitSkydome;var alpha=m.Shader switch{SageShaderType.Boundary or SageShaderType.Invisible=>0f,SageShaderType.Transparent25=>.25f,SageShaderType.Transparent50=>.5f,SageShaderType.Transparent75=>.75f,_=>1f};var additive=m.Shader is SageShaderType.TransparentAdditive or SageShaderType.TransparentAdditiveUnlit or SageShaderType.TransparentAdditiveUnlitSkydome;var unlit=m.Shader is SageShaderType.TransparentAdditiveUnlit or SageShaderType.TransparentAdditiveUnlitSkydome;var mat=new RenderMaterial(m.Name,tex,m.Shader.ToString(),alpha,m.Shader==SageShaderType.TransparentMasked,additive,unlit,processed,m.AnimationDelayMs,m.CurrentFrame,m.Brightness,m.ScaledAmbient,m.SkipFrames,blend);var morph=p.MorphFrames?.Select(frame=>new RenderMorphFrame(frame.PositionDeltas,frame.DelayMs)).ToArray();return new RenderPrimitive(p.Name,p.Vertices.Select(v=>new RenderVertex(v.Position,v.Normal,v.Uv,v.SourceIndex,0,v.Color)).ToArray(),p.Indices,tex,p.PassThrough,mat,morph);}).ToArray();
   _renderMeshes[key]=new(sm.Name,rp,scene.FlipRootX);
  }
 }
 bool TryRawEqgTexture(string name,out byte[] data){foreach(var key in new[]{name,Path.GetFileName(name),Path.GetFileNameWithoutExtension(name)})if(_rawTextures.TryGetValue(key,out data!))return true;data=Array.Empty<byte>();return false;}
 void RegisterEqgModel(string archive,SageEqgModel model,IReadOnlyList<uint>? lit=null)
 {
  var prims=new List<RenderPrimitive>();
  foreach(var group in model.Polygons.Where(p=>p.Material>=0&&p.Material<model.Materials.Count).GroupBy(p=>p.Material)){
   var mat=model.Materials[group.Key];var verts=new List<RenderVertex>();var idx=new List<ushort>();string? textureNative=null;string? normalNative=null;
   foreach(var prop in mat.Properties){if(prop.Type!=2||string.IsNullOrWhiteSpace(prop.StringValue))continue;if(prop.Name.Contains("Normal",StringComparison.OrdinalIgnoreCase))normalNative=prop.StringValue;if(prop.Name.Contains("Diffuse",StringComparison.OrdinalIgnoreCase)||(prop.Name.Contains("Detail",StringComparison.OrdinalIgnoreCase)&&textureNative is null))textureNative=prop.StringValue;}
   string? tex=null;if(textureNative is not null&&TryRawEqgTexture(textureNative,out var raw)){var key=Path.GetFileNameWithoutExtension(textureNative).ToLowerInvariant()+"-eqg.png";if(!_textureFiles.ContainsKey(key))_textureFiles[key]=SageTextureProcessor.Process(textureNative,raw,SageShaderType.Diffuse);tex=key;}string? normalTex=null;if(normalNative is not null&&TryRawEqgTexture(normalNative,out var nraw)){var nk=Path.GetFileNameWithoutExtension(normalNative).ToLowerInvariant()+"-eqg-normal.png";if(!_textureFiles.ContainsKey(nk))_textureFiles[nk]=SageTextureProcessor.Process(normalNative,nraw,SageShaderType.Diffuse);normalTex=nk;}
   foreach(var p in group){foreach(var vi in new[]{p.A,p.C,p.B}){if(vi>=model.Vertices.Count)throw new InvalidDataException($"EQG model '{model.Name}' polygon vertex index {vi} is out of range.");var v=model.Vertices[(int)vi];idx.Add(checked((ushort)verts.Count));var color=lit is not null&&vi<lit.Count?lit[(int)vi]:v.Color;var weighted=v.Weights?.Where(w=>w.Bone>=0&&w.Weight>0).Take(4).ToArray()??Array.Empty<SageEqgWeight>();var boneIndex=weighted.FirstOrDefault()?.Bone??0;var influences=weighted.Select(w=>new RenderSkinInfluence(w.Bone,w.Weight)).ToArray();verts.Add(new(v.Position,v.Normal,new(-v.Uv.X,v.Uv.Y),(int)vi,boneIndex,color,influences));}}
   var alpha=mat.Shader.StartsWith("Alpha",StringComparison.OrdinalIgnoreCase)||mat.Shader.StartsWith("Chroma",StringComparison.OrdinalIgnoreCase);var rm=new RenderMaterial(mat.Name,tex,mat.Shader,1f,false,false,false,tex is null?Array.Empty<string>():new[]{tex},AlphaBlend:alpha,NormalTextureName:normalTex);var hasBones=model.Bones.Count>0;prims.Add(new(mat.Name,verts,idx,tex,hasBones,rm));
  }
  if(prims.Count==0)return;RenderSkeleton? skeleton=null;if(model.Bones.Count>0){var parents=Enumerable.Repeat(-1,model.Bones.Count).ToArray();for(var bi=0;bi<model.Bones.Count;bi++){var b=model.Bones[bi];var child=b.ChildrenIndex;for(var ci=0;ci<b.ChildrenCount&&child>=0&&child<model.Bones.Count;ci++){parents[child]=bi;child=model.Bones[child].Next;}}var rb=model.Bones.Select((b,i)=>new RenderBone(b.Name,parents[i],b.Translation,b.Rotation,(b.Scale.X+b.Scale.Y+b.Scale.Z)/3f)).ToArray();skeleton=new RenderSkeleton(rb);}var animations=BuildEqgAnimations(model);var asset=$"eqg:{archive}#{model.Name}";_renderMeshes[asset]=new(model.Name,prims,false,skeleton,animations);_nativeAssets[Path.GetFileNameWithoutExtension(model.Name).ToLowerInvariant()]=asset;
 }
